(async()=>{
 const wait=()=>new Promise(r=>setTimeout(r,180)),check=(v,m)=>{if(!v)throw Error(m)};
 const go=async(path)=>{location.hash=path;await wait()};
 const click=async(text,scope=document)=>{const el=[...scope.querySelectorAll('button,a')].find(e=>e.textContent.trim()===text);check(el,'Missing '+text);el.click();await wait()};
 const fill=async(label,value)=>{const field=[...document.querySelectorAll('.field')].find(e=>e.querySelector('label')?.textContent.replace(' *','').trim()===label),el=field?.querySelector('input:not([type=hidden]),textarea');check(el,'Missing '+label);Object.getOwnPropertyDescriptor(el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 const choose=async(label,text)=>{const el=document.querySelector(`[role=combobox][aria-label="${label}"]`);check(el,'Missing '+label);el.click();await wait();await click(text,document.querySelector('[role=listbox]'));};
 const state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1')),main=()=>document.querySelector('main');
 await go('/machines');check(main().textContent.includes('接入节点'),'List installation missing');
 await go('/machines/n1?tab=preview');check(![...main().querySelectorAll('button')].some(e=>e.textContent.trim()==='接入节点'),'Node detail creates new node');check(!main().textContent.includes('资源所属项目'),'Permanent project picker remains');
 const previewLinks=[...main().querySelectorAll('a')];check(!previewLinks.some(link=>link.textContent.includes('新标签页查看示例成果')||/W-104|artifacts/.test(link.getAttribute('href')||'')),'Unbound node fabricated a task artifact preview link');check(main().textContent.includes('当前未登记任务关联，不能打开其他任务的成果')&&main().textContent.includes('没有可核对的项目租约'),'Unbound node preview implies verified task or live lease evidence');
 await go('/performance');await click('模拟周期生成');check(document.querySelector('dialog[open]')?.textContent.includes('先配置并启用考核方案'),'Missing scheme must explain the prerequisite rather than silently disable generation');check(!state()?.resources.performanceReports?.length,'Missing scheme fabricated a report');await click('配置考核方案',document.querySelector('dialog[open]')); let dialog=document.querySelector('dialog[open]');
 const subjects=[...dialog.querySelectorAll('fieldset')].find(e=>e.querySelector('legend')?.textContent.includes('考核主体'));const human=[...subjects.querySelectorAll('label')].find(e=>e.textContent.includes('林予')),agent=[...subjects.querySelectorAll('label')].find(e=>e.textContent.includes('Agent'));check(human&&agent,'Human/Agent choices missing');human.querySelector('input').click();agent.querySelector('input').click();await wait();
 await click('移除细则 1',dialog);await fill('配置变更理由','小项目周期评估试运行，仅使用有证据的专业评估');await click('保存方案修订',dialog);check(state().resources.performancePolicies?.length===1,'Policy not saved');
 await click('模拟周期生成');await fill('周期内任一日期','2026-10-04');await fill('生成或重新计算理由','模拟上一完整周批量生成');await click('生成所选成员报告');
 check(state().resources.performanceReports?.length===2,'Batch human+agent generation incomplete');check(main().textContent.includes('不计分')&&!main().textContent.includes('确认本修订评分'),'Tenant view has assessment score');
 const policy=state().resources.performancePolicies[0],report=state().resources.performanceReports.find(r=>r.subject.key==='human:H-lin');check(report,'Human report missing');await choose('查看主体','林予 · Human');check(location.hash.includes('human%3AH-lin'),'Subject deep link missing');check(main().textContent.includes('按项目')||main().textContent.includes('项目'),'Project breakdown absent');
 await click('专业校准 · 专业质量评估');await fill('专业评估次数','2');await fill('HTTP(S) 证据地址','https://example.com/review/fixed-1');await fill('专业校准或确认理由','已核对两项专业质量材料');await click('保存决定');
 await click('确认本修订评分');await fill('专业校准或确认理由','负责人复核固定依据后确认');await click('保存决定');check(state().resources.performanceReports.find(r=>r.id===report.id).status==='已确认','Score not confirmed');
 await choose('查看主体','租户汇总 · 不计分');await click('返回周期列表');check(main().textContent.includes('2026-09-28'),'Period list missing');check(document.documentElement.scrollWidth<=innerWidth,'Performance overflows');
 return {pass:true,width:innerWidth,policy:policy.id,humanReport:report.id,assertions:['node-detail-boundary','no-fabricated-node-preview','period-generation','tenant-no-score','human-agent-distinct','calibration-confirmation','period-list']};
})();
